html:
{# ── Cancelled Watermark ─────────────────────────────────────────────────────── #}
{% set _is_einv_cancelled = doc.einvoice_status in ('Cancelled', 'Manually Cancelled') %}
{% set _is_ewb_cancelled  = doc.get('e_waybill_status') in ('Cancelled', 'Manually Cancelled') %}
{% set _show_cancelled    = _is_einv_cancelled or _is_ewb_cancelled %}
{% if _show_cancelled %}
<style>
.ib-cancelled-watermark {
    position: fixed;
    top: 0; left: 0;
    width: 100vw; height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    pointer-events: none;
    z-index: 99999;
    overflow: hidden;
}
.ib-cancelled-watermark span {
    display: block;
    font-size: 110px;
    font-weight: 900;
    color: rgba(220, 38, 38, 0.18);
    letter-spacing: 10px;
    text-transform: uppercase;
    white-space: nowrap;
    transform: rotate(-40deg);
    font-family: Arial, sans-serif;
    border: 14px solid rgba(220, 38, 38, 0.15);
    padding: 10px 30px;
    border-radius: 8px;
    line-height: 1;
}
</style>
<div class="ib-cancelled-watermark"><span>CANCELLED</span></div>
{% endif %}

{# ── Company ──────────────────────────────────────────────────────────────────── #}
{% set co = frappe.get_doc("Company", doc.company) %}
{% set co_addr = frappe.db.get_value("Address", doc.company_address,
    ["address_line1","address_line2","city","state","pincode"], as_dict=True)
    if doc.company_address else None %}

{# ── e-Invoice Log ────────────────────────────────────────────────────────────── #}
{% set einv = frappe.db.get_value("e-Invoice Log",
    {"reference_doctype": "Sales Invoice", "reference_name": doc.name},
    ["irn","signed_qr_code","acknowledgement_number","acknowledged_on"], as_dict=True) %}
{% set _irn = (einv.irn if einv else None) or doc.irn or "" %}

{# ── e-Waybill Log ────────────────────────────────────────────────────────────── #}
{% set ewb_log = frappe.db.get_value("e-Waybill Log",
    {"reference_doctype": "Sales Invoice", "reference_name": doc.name, "is_cancelled": 0},
    ["data","e_waybill_number","created_on","valid_upto"], as_dict=True) %}
{% if not ewb_log %}
  {% set ns_dn = namespace(v=[]) %}
  {% for item in doc.items %}
    {% if item.delivery_note and item.delivery_note not in ns_dn.v %}
      {% set _ = ns_dn.v.append(item.delivery_note) %}
    {% endif %}
  {% endfor %}
  {% if ns_dn.v %}
    {% set ewb_log = frappe.db.get_value("e-Waybill Log",
        {"reference_doctype": "Delivery Note", "reference_name": ns_dn.v[0], "is_cancelled": 0},
        ["data","e_waybill_number","created_on","valid_upto"], as_dict=True) %}
  {% endif %}
{% endif %}
{% set ewb = _dict(json.loads(ewb_log.data)) if ewb_log and ewb_log.data else None %}

{# ── Customer Addresses ───────────────────────────────────────────────────────── #}
{% set ship_name = doc.shipping_address_name or doc.customer_address %}
{% set ship_addr = frappe.db.get_value("Address", ship_name,
    ["address_line1","address_line2","city","state","pincode","gstin","phone"], as_dict=True)
    if ship_name else None %}
{% set bill_addr = frappe.db.get_value("Address", doc.customer_address,
    ["address_line1","address_line2","city","state","pincode","gstin","phone"], as_dict=True)
    if doc.customer_address else None %}

{# ── Delivery Notes ───────────────────────────────────────────────────────────── #}
{% set ns = namespace(dn_list=[]) %}
{% for item in doc.items %}
  {% if item.delivery_note and item.delivery_note not in ns.dn_list %}
    {% set _ = ns.dn_list.append(item.delivery_note) %}
  {% endif %}
{% endfor %}
{% set first_dn = frappe.db.get_value("Delivery Note", ns.dn_list[0],
    ["name","posting_date","lr_no","custom_lr_number","vehicle_no","transporter_name"], as_dict=True)
    if ns.dn_list else None %}

{# ── Bank Details via Warehouse ───────────────────────────────────────────────── #}
{% set wh_name = doc.set_warehouse or (doc.items[0].warehouse if doc.items else None) %}
{% set ba_name = frappe.db.get_value("Warehouse", wh_name, "custom_bank_details") if wh_name else None %}
{% set ba = frappe.db.get_value("Bank Account", ba_name,
    ["account_name","bank","bank_account_no","branch_code","company"], as_dict=True)
    if ba_name else None %}
{% set bank_display = frappe.db.get_value("Bank", ba.bank, "bank_name") if ba and ba.bank else (ba.bank if ba else "") %}

{# ── GSTIN / State codes ──────────────────────────────────────────────────────── #}
{% set co_state_code   = doc.company_gstin[:2]|int if doc.company_gstin and doc.company_gstin|length >= 2 else 0 %}
{% set cust_gstin      = (ship_addr.gstin if ship_addr and ship_addr.gstin else None) or doc.billing_address_gstin or "" %}
{% set cust_state_code = cust_gstin[:2]|int if cust_gstin|length >= 2 else 0 %}
{% set bill_gstin      = (bill_addr.gstin if bill_addr and bill_addr.gstin else None) or doc.billing_address_gstin or "" %}
{% set bill_state_code = bill_gstin[:2]|int if bill_gstin|length >= 2 else 0 %}

{# ── Logistics ────────────────────────────────────────────────────────────────── #}
{% set vehicle_no = doc.vehicle_no or (first_dn.vehicle_no if first_dn else "") or "" %}
{% if not vehicle_no and ewb and ewb.VehiclListDetails %}
  {% set vehicle_no = ewb.VehiclListDetails[-1].vehicleNo or "" %}
{% endif %}
{% set transporter = doc.transporter_name
    or (first_dn.transporter_name if first_dn else "")
    or (ewb.transporterName if ewb else "") or "" %}
{% set destination = (ewb.toPlace if ewb else "") or "" %}
{% set lr_no = doc.lr_no
    or (first_dn.lr_no if first_dn else "")
    or (first_dn.custom_lr_number if first_dn else "") or "" %}
{% set ewb_number = (ewb.ewbNo|string if ewb else "") or (ewb_log.e_waybill_number|string if ewb_log and ewb_log.e_waybill_number else "") or doc.ewaybill or "" %}

{# ── Customer Balance ─────────────────────────────────────────────────────────── #}
{% set prev_rows = frappe.db.sql(
    "SELECT COALESCE(SUM(outstanding_amount),0) FROM `tabSales Invoice`"
    " WHERE customer=%s AND docstatus=1 AND outstanding_amount>0 AND name!=%s",
    (doc.customer, doc.name)) %}
{% set prev_bal = prev_rows[0][0]|float if prev_rows else 0 %}
{% set bill_amt = (doc.rounded_total or doc.grand_total or 0)|float %}
{% set net_bal  = prev_bal + bill_amt %}

{# ── Helpers ──────────────────────────────────────────────────────────────────── #}
{% macro fd(d) %}{% if d %}{{ frappe.utils.formatdate(d, "dd-MMM-yy") }}{% endif %}{% endmacro %}
{% macro fm(v) %}{{ frappe.utils.fmt_money(v|float, precision=2) }}{% endmacro %}

{# ── Address formatter ────────────────────────────────────────────────────────── #}
{% macro addr_block(a, name, gstin, state_code) %}
{% if a %}
<div><strong>{{ name }}</strong></div>
{% if a.address_line1 %}<div>{{ a.address_line1 }}{% if a.address_line2 %}, {{ a.address_line2 }}{% endif %}</div>{% endif %}
{% if a.city or a.state %}
<div>{{ a.city or "" }}{% if a.state %}, {{ a.state }}{% endif %}{% if a.pincode %}, {{ a.pincode }}{% endif %}</div>
{% endif %}
{% else %}
<div><strong>{{ name }}</strong></div>
{% endif %}
<div>GSTIN/UIN : <strong>{{ gstin or "—" }}</strong></div>
<div>State Name : {% if state_code %}{{ get_state(state_code) }}, Code : {{ state_code }}{% else %}—{% endif %}</div>
{% endmacro %}

<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: Arial, sans-serif; font-size: 10px; color: #000; line-height: 1.45; }
  table { width: 100%; border-collapse: collapse; }
  td, th { vertical-align: top; padding: 3px 5px; }
  strong, b { font-weight: bold; }
  .right { text-align: right; }
  .center { text-align: center; }
  .italic { font-style: italic; }
  .lbl { color: #444; }
  .small { font-size: 9px; }

  .inv-frame { border: 1px solid #000; border-collapse: collapse; }
  .inv-frame td, .inv-frame th { border: 1px solid #777; }

  .it-tbl { border: 1px solid #000; border-collapse: collapse; }
  .it-tbl th { border: 1px solid #777; background: #f0f0f0; font-weight: bold;
               text-align: center; padding: 4px 4px; font-size: 10px; }
  .it-tbl td { border: 1px solid #ccc; padding: 3px 5px; }
  .it-tbl .no-border td { border: none; }
  .it-tbl .top-line td { border-top: 1px solid #999; border-left: none;
                          border-right: none; border-bottom: none; }

  .bot-frame { border-top: 1px solid #000; }
  .kv td { padding: 1px 4px 1px 0; }
  .kv td:first-child { white-space: nowrap; color: #444; }
  img { display: block; }
</style>

{# ════════════════════════════════════════════════════════════════════════════════ #}
{# PAGE 1 — TAX INVOICE                                                             #}
{# ════════════════════════════════════════════════════════════════════════════════ #}

<table style="margin-bottom:2px">
  <tr>
    <td class="center" style="font-size:13px; font-weight:bold; padding:2px 0">Tax Invoice</td>
    <td class="right" style="padding:2px 0">
      {% if _irn %}<span style="font-size:11px; font-weight:bold">e-Invoice</span>{% endif %}
    </td>
  </tr>
</table>

<table style="margin-bottom:4px">
  <tr>
    <td style="width:65%; vertical-align:top; padding-right:8px">
      {% if _irn %}
      <div><span class="lbl">IRN &nbsp;&nbsp;&nbsp;&nbsp;:</span> <strong>{{ _irn }}</strong></div>
      {% if einv %}
      <div><span class="lbl">Ack No. :</span> <strong>{{ einv.acknowledgement_number or "" }}</strong></div>
      <div><span class="lbl">Ack Date:</span> <strong>{{ fd(einv.acknowledged_on) }}</strong></div>
      {% endif %}
      {% endif %}
    </td>
    <td style="width:35%; text-align:right; vertical-align:top">
      {% if einv and einv.signed_qr_code %}
      <img src="data:image/png;base64,{{ get_qr_code(einv.signed_qr_code, scale=2) }}"
           style="height:80px; width:auto; display:inline-block">
      {% endif %}
    </td>
  </tr>
</table>

<table class="inv-frame">
  <tr>
    <td style="width:42%; border-right:1px solid #000; padding:5px 7px; vertical-align:top">
      <table style="border:none; margin-bottom:3px">
        <tr>
          <td style="border:none; padding:0 8px 0 0; width:60px; vertical-align:middle">
            <img src="/files/letterhead.jpeg"
                 style="width:58px; height:auto; max-height:50px; object-fit:contain">
          </td>
          <td style="border:none; padding:0; vertical-align:middle">
            <div style="font-size:11px; font-weight:bold; line-height:1.3">{{ doc.company | upper }}</div>
          </td>
        </tr>
      </table>
      {% if co_addr %}
      <div>{{ co_addr.address_line1 or "" }}{% if co_addr.address_line2 %}, {{ co_addr.address_line2 }}{% endif %}</div>
      {% if co_addr.city or co_addr.state %}
      <div>{% if co_addr.city %}{{ co_addr.city }},{% endif %} {% if co_addr.state %}{{ co_addr.state }}{% endif %}{% if co_addr.pincode %} {{ co_addr.pincode }}{% endif %}</div>
      {% endif %}
      {% endif %}
      <div>GSTIN/UIN: <strong>{{ doc.company_gstin or "—" }}</strong></div>
      {% if co_state_code %}
      <div>State Name : {{ get_state(co_state_code) }}, Code : {{ co_state_code }}</div>
      {% endif %}
      {% if co.phone_no %}<div>Contact : <strong>{{ co.phone_no }}</strong></div>{% endif %}
      {% if co.email %}<div>E-Mail : <strong>{{ co.email }}</strong></div>{% endif %}
    </td>

    <td style="width:58%; padding:0; vertical-align:top">
      <table style="border:none; border-collapse:collapse; width:100%">

        <tr>
          <td style="width:36%; border-bottom:1px solid #aaa; border-right:1px solid #aaa; padding:3px 5px">
            <div class="lbl small">Invoice No.</div>
            <div><strong>{{ doc.name }}</strong></div>
          </td>
          <td style="width:36%; border-bottom:1px solid #aaa; border-right:1px solid #aaa; padding:3px 5px">
            <div class="lbl small">e-Way Bill No.</div>
            <div><strong>{{ ewb_number or "" }}</strong></div>
          </td>
          <td style="width:28%; border-bottom:1px solid #aaa; padding:3px 5px">
            <div class="lbl small">Dated</div>
            <div><strong>{{ fd(doc.posting_date) }}</strong></div>
          </td>
        </tr>

        <tr>
          <td colspan="2" style="border-bottom:1px solid #aaa; border-right:1px solid #aaa; padding:3px 5px">
            <div class="lbl small">Delivery Note</div>
            {% for dn_n in ns.dn_list %}
              {% set dn_d = frappe.db.get_value("Delivery Note", dn_n, "posting_date") %}
              <div><strong>{{ dn_n }}</strong>{% if dn_d %} dt. {{ fd(dn_d) }}{% endif %}</div>
            {% endfor %}
          </td>
          <td style="border-bottom:1px solid #aaa; padding:3px 5px">
            <div class="lbl small">Mode/Terms of Payment</div>
            <div>{{ doc.payment_terms_template or "" }}</div>
          </td>
        </tr>

        <tr>
          <td colspan="2" style="border-bottom:1px solid #aaa; border-right:1px solid #aaa; padding:3px 5px">
            <div class="lbl small">Reference No. &amp; Date.</div>
            {% if doc.po_no %}
            <div><strong>{{ doc.po_no }}</strong>{% if doc.po_date %} dt. {{ fd(doc.po_date) }}{% endif %}</div>
            {% endif %}
          </td>
          <td style="border-bottom:1px solid #aaa; padding:3px 5px">
            <div class="lbl small">Other References</div>
          </td>
        </tr>

        <tr>
          <td colspan="2" style="border-bottom:1px solid #aaa; border-right:1px solid #aaa; padding:3px 5px; height:28px">
            <div class="lbl small">Buyer's Order No.</div>
          </td>
          <td style="border-bottom:1px solid #aaa; padding:3px 5px">
            <div class="lbl small">Dated</div>
          </td>
        </tr>

        <tr>
          <td colspan="2" style="border-bottom:1px solid #aaa; border-right:1px solid #aaa; padding:3px 5px; height:28px">
            <div class="lbl small">Dispatch Doc No.</div>
          </td>
          <td style="border-bottom:1px solid #aaa; padding:3px 5px">
            <div class="lbl small">Delivery Note Date</div>
            {% if first_dn %}
            <div>{{ fd(first_dn.posting_date) }}</div>
            {% endif %}
          </td>
        </tr>

        <tr>
          <td colspan="2" style="border-bottom:1px solid #aaa; border-right:1px solid #aaa; padding:3px 5px">
            <div class="lbl small">Dispatched through</div>
            <div><strong>{{ transporter | upper }}</strong></div>
          </td>
          <td style="border-bottom:1px solid #aaa; padding:3px 5px">
            <div class="lbl small">Destination</div>
            <div><strong>{{ destination | upper }}</strong></div>
          </td>
        </tr>

        <tr>
          <td colspan="2" style="border-bottom:1px solid #aaa; border-right:1px solid #aaa; padding:3px 5px; height:28px">
            <div class="lbl small">Bill of Lading/LR-RR No.</div>
            {% if lr_no %}<div><strong>{{ lr_no }}</strong></div>{% endif %}
          </td>
          <td style="border-bottom:1px solid #aaa; padding:3px 5px">
            <div class="lbl small">Motor Vehicle No.</div>
            {% if vehicle_no %}<div><strong>{{ vehicle_no | upper }}</strong></div>{% endif %}
          </td>
        </tr>

        <tr>
          <td colspan="3" style="padding:3px 5px; height:30px">
            <div class="lbl small">Terms of Delivery</div>
          </td>
        </tr>

      </table>
    </td>
  </tr>

  <tr>
    <td colspan="2" style="padding:0; border-top:1px solid #000">
      <table style="border:none; border-collapse:collapse; width:100%">
        <tr>
          <td style="width:42%; border-right:1px solid #777; padding:4px 7px; vertical-align:top">
            <div class="lbl small"><strong>Consignee (Ship to)</strong></div>
            {{ addr_block(ship_addr, doc.customer_name, cust_gstin, cust_state_code) }}
            {% if doc.contact_display %}
            <div>Contact person : <strong>{{ doc.contact_display }}</strong></div>
            {% endif %}
            {% if doc.contact_mobile %}
            <div>Contact &nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : <strong>{{ doc.contact_mobile }}</strong></div>
            {% endif %}
          </td>
          <td style="width:58%; vertical-align:top; padding:0"></td>
        </tr>
      </table>
    </td>
  </tr>

  <tr>
    <td colspan="2" style="padding:0; border-top:1px solid #777">
      <table style="border:none; border-collapse:collapse; width:100%">
        <tr>
          <td style="width:42%; border-right:1px solid #777; padding:4px 7px; vertical-align:top">
            <div class="lbl small">Buyer (Bill to)</div>
            {{ addr_block(bill_addr, doc.customer_name, bill_gstin, bill_state_code) }}
            {% if doc.contact_display %}
            <div>Contact person : <strong>{{ doc.contact_display }}</strong></div>
            {% endif %}
            {% if doc.contact_mobile %}
            <div>Contact &nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : <strong>{{ doc.contact_mobile }}</strong></div>
            {% endif %}
          </td>
          <td style="width:58%; padding:4px 7px; vertical-align:top">
            {% if doc.is_reverse_charge %}
            <div><strong>Reverse Charge: Yes</strong></div>
            {% endif %}
            {% if doc.place_of_supply %}
            <div class="lbl small">Place of Supply: <strong>{{ doc.place_of_supply }}</strong></div>
            {% endif %}
          </td>
        </tr>
      </table>
    </td>
  </tr>

</table>

<table class="it-tbl" style="margin-top:0">
  <thead>
    <tr>
      <th style="width:4%">Sl<br>No.</th>
      <th>Description of Goods</th>
      <th style="width:9%">HSN/SAC</th>
      <th style="width:6%">GST<br>Rate</th>
      <th style="width:14%">Quantity</th>
      <th style="width:8%">Rate</th>
      <th style="width:7%">per</th>
      <th style="width:11%">Amount</th>
    </tr>
  </thead>
  <tbody>
    {% set ns_doc = namespace(doc_gst=0) %}
    {% for t in doc.taxes %}
      {% set ns_doc.doc_gst = ns_doc.doc_gst + (t.rate or 0) %}
    {% endfor %}

    {% for row in doc.items %}
    {% set ns_t = namespace(gst=0) %}
    {% if row.item_tax_rate %}
      {% for _acct, _r in json.loads(row.item_tax_rate).items() %}
        {% set ns_t.gst = ns_t.gst + _r %}
      {% endfor %}
    {% endif %}
    {% if ns_t.gst == 0 %}{% set ns_t.gst = ns_doc.doc_gst %}{% endif %}
    <tr>
      <td class="center">{{ loop.index }}</td>
      <td>
        <strong>{{ row.item_name or row.item_code }}</strong>
        {% set ns_s = namespace(v="") %}
        {% if row.item_code %}{% set ns_s.v = row.item_code %}{% endif %}
        {% if row.custom_thickness %}{% set ns_s.v = ns_s.v + " " + row.custom_thickness %}{% endif %}
        {% if row.width_mm and row.length_mtr %}
          {% set ns_s.v = ns_s.v + " " + (row.width_mm|int)|string + "*" + (row.length_mtr|int)|string %}
        {% endif %}
        {% if row.qty_pkg %}{% set ns_s.v = ns_s.v + " " + row.qty_pkg|string + "ROLL" %}{% endif %}
        {% set _cm = frappe.db.get_value("Item", row.item_code, "custom_carton_marking") or "" %}
        {% if _cm %}{% set ns_s.v = ns_s.v + " " + _cm %}{% endif %}
        {% if row.color %}{% set ns_s.v = ns_s.v + " " + row.color %}{% endif %}
        {% if ns_s.v | trim %}
        <br><span class="italic lbl" style="font-size:9px">{{ ns_s.v | trim }}</span>
        {% endif %}
      </td>
      <td class="center">{{ row.gst_hsn_code or "" }}</td>
      <td class="center">{{ "%g" | format(ns_t.gst) }} %</td>
      <td class="right"><strong>{{ fm(row.qty) }}</strong> {{ row.uom }}</td>
      <td class="right"><strong>{{ fm(row.rate) }}</strong></td>
      <td class="center">{{ row.uom }}</td>
      <td class="right"><strong>{{ fm(row.amount) }}</strong></td>
    </tr>
    {% endfor %}

    <tr>
      <td colspan="7" style="border:none; border-top:1px solid #aaa; text-align:right; padding:2px 5px"></td>
      <td class="right" style="border-top:1px solid #aaa; border-left:1px solid #ccc; border-right:1px solid #ccc; border-bottom:none">
        <strong>{{ fm(doc.net_total) }}</strong>
      </td>
    </tr>

    {% for tax in doc.taxes %}
    {% if tax.tax_amount %}
    <tr class="italic">
      <td colspan="5" class="right" style="border:none; padding:2px 5px">
        <em>{{ tax.description }} {{ "%g" | format(tax.rate) }} %</em>
      </td>
      <td class="right" style="border:1px solid #ccc">{{ "%g" | format(tax.rate) }}</td>
      <td class="center" style="border:1px solid #ccc">%</td>
      <td class="right" style="border:1px solid #ccc">{{ fm(tax.tax_amount) }}</td>
    </tr>
    {% endif %}
    {% endfor %}

    {% for _i in range(4) %}
    <tr style="height:14px">
      <td colspan="8" style="border:none"></td>
    </tr>
    {% endfor %}

    <tr>
      <td colspan="7" class="right"
          style="border-top:1.5px solid #000; border-left:none; border-right:none; border-bottom:none;
                 font-weight:bold; padding:4px 5px">
        Total
      </td>
      <td class="right"
          style="border:1px solid #000; border-top:1.5px solid #000;
                 font-weight:bold; font-size:11px; padding:4px 5px">
        ₹ {{ fm(doc.rounded_total or doc.grand_total) }}
      </td>
    </tr>
  </tbody>
</table>

<table style="border:1px solid #aaa; border-top:none; border-collapse:collapse">
  <tr>
    <td style="width:70%; border-right:1px solid #aaa; padding:4px 6px">
      <span class="lbl small">Amount Chargeable (in words)</span><br>
      <strong>{{ doc.in_words or "" }}</strong>
    </td>
    <td class="right italic lbl" style="padding:4px 6px; vertical-align:bottom">E. &amp; O.E</td>
  </tr>
</table>

{% if doc.gst_breakup_table %}
<div style="margin-top:4px">{{ doc.gst_breakup_table }}</div>
{% endif %}

<table style="margin-top:6px; border-top:1px solid #000; border-collapse:collapse">
  <tr>
    <td style="width:48%; vertical-align:top; border-right:1px solid #aaa; padding:5px 8px 5px 0">

      <table class="kv" style="margin-bottom:8px">
        <tr><td>Prev. Balance :</td><td><strong>{{ fm(prev_bal) }} Dr</strong></td></tr>
        <tr><td>Bill Amount &nbsp;:</td><td style="border-bottom:1px solid #555"><strong>{{ fm(bill_amt) }} Dr</strong></td></tr>
        <tr><td>Net Balance &nbsp;:</td><td><strong>{{ fm(net_bal) }} Dr</strong></td></tr>
