        <tr><td>Bank Name</td><td>: <strong>{{ bank_display or ba.bank or "" }} (Mumbai)</strong></td></tr>
        <tr><td>A/c No.</td><td>: <strong>{{ ba.bank_account_no }}</strong></td></tr>
