{# PAGE 2 — e-WAY BILL                                                              #}
{# ════════════════════════════════════════════════════════════════════════════════ #}
{% if ewb %}
<div style="page-break-before:always">

  <table>
    <tr>
      <td style="width:70%; vertical-align:top">
        <strong style="font-size:14px">e-Way Bill</strong>
        <table class="kv" style="margin-top:5px">
          <tr><td>Doc No.</td><td>: <strong>Tax Invoice – {{ doc.name }}</strong></td></tr>
          <tr><td>Date &nbsp;&nbsp;</td><td>: <strong>{{ fd(doc.posting_date) }}</strong></td></tr>
        </table>
        <table class="kv" style="margin-top:5px">
          <tr><td>IRN &nbsp;&nbsp;&nbsp;&nbsp;</td><td>: {{ _irn or "—" }}</td></tr>
          {% if einv %}
          <tr><td>Ack No.</td><td>: <strong>{{ einv.acknowledgement_number or "—" }}</strong></td></tr>
          <tr><td>Ack Date</td><td>: <strong>{{ fd(einv.acknowledged_on) if einv.acknowledged_on else "—" }}</strong></td></tr>
          {% endif %}
        </table>
      </td>
      <td style="width:30%; text-align:right; vertical-align:top">
        <img src="data:image/png;base64,{{ get_e_waybill_qr_code(ewb.ewbNo, ewb.userGstin, ewb.ewayBillDate) }}"
             style="height:90px; width:auto; display:inline-block">
      </td>
    </tr>
  </table>

  <hr style="border:0; border-top:1.5px solid #222; margin:6px 0">

  <div style="font-weight:bold; padding:3px 6px; margin:6px 0 4px;
              border-top:1px solid #555; border-bottom:1px solid #555; background:#f5f5f5">
    1. e-Way Bill Details
  </div>
  <table>
    <tr>
      <td style="width:34%"><span class="lbl">e-Way Bill No. :</span> <strong>{{ ewb.ewbNo }}</strong></td>
      <td style="width:33%"><span class="lbl">Generated Date :</span> <strong>{{ ewb.ewayBillDate }}</strong></td>
      <td style="width:33%"><span class="lbl">Generated By :</span> <strong>{{ ewb.userGstin }}</strong></td>
    </tr>
    <tr>
      <td>
        {% set _lastVeh = ewb.VehiclListDetails[-1] if ewb.VehiclListDetails else None %}
        <span class="lbl">Mode :</span>
        <strong>{% if _lastVeh %}{{ _lastVeh.transMode }}{% else %}1{% endif %} – Road</strong>
      </td>
      <td><span class="lbl">Approx Distance :</span> <strong>{{ ewb.actualDist }} KM</strong></td>
      <td><span class="lbl">Valid Upto :</span> <strong>{{ ewb.validUpto }}</strong></td>
    </tr>
    <tr>
      <td><span class="lbl">Supply Type :</span> <strong>Outward – Supply</strong></td>
      <td colspan="2"><span class="lbl">Transaction Type :</span> <strong>Regular</strong></td>
    </tr>
  </table>

  <div style="font-weight:bold; padding:3px 6px; margin:6px 0 4px;
              border-top:1px solid #555; border-bottom:1px solid #555; background:#f5f5f5">
    2. Address Details
  </div>
  <table>
    <tr>
      <td style="width:50%; vertical-align:top; padding-right:10px">
        <div><strong>From</strong></div>
        <div style="margin-top:3px">
          <div><strong>{{ ewb.fromTrdName or doc.company }}</strong></div>
          <div>GSTIN : <strong>{{ ewb.fromGstin or doc.company_gstin }}</strong></div>
          <div>{{ get_state(ewb.fromStateCode|int) if ewb.fromStateCode else "" }}</div>
        </div>
        <div style="margin-top:6px">
          <div><strong>Dispatch From</strong></div>
          <div>{{ ewb.fromAddr1 or "" }}{% if ewb.fromAddr2 %}, {{ ewb.fromAddr2 }}{% endif %}</div>
          <div>{{ ewb.fromPlace or "" }} {{ get_state(ewb.actFromStateCode|int) if ewb.actFromStateCode else "" }} {{ ewb.fromPincode or "" }}</div>
        </div>
      </td>
      <td style="width:50%; vertical-align:top; border-left:1px solid #ccc; padding-left:10px">
        <div><strong>To</strong></div>
        <div style="margin-top:3px">
          <div><strong>{{ ewb.toTrdName or doc.customer_name }}</strong></div>
          <div>GSTIN : <strong>{{ ewb.toGstin or doc.billing_address_gstin or "—" }}</strong></div>
          <div>{{ get_state(ewb.toStateCode|int) if ewb.toStateCode else "" }}</div>
        </div>
        <div style="margin-top:6px">
          <div><strong>Ship To</strong></div>
          <div>{{ ewb.toAddr1 or "" }}{% if ewb.toAddr2 %}, {{ ewb.toAddr2 }}{% endif %}</div>
          <div>{{ ewb.toPlace or "" }} {{ get_state(ewb.actToStateCode|int) if ewb.actToStateCode else "" }} {{ ewb.toPincode or "" }}</div>
        </div>
      </td>
    </tr>
  </table>

  <div style="font-weight:bold; padding:3px 6px; margin:6px 0 4px;
              border-top:1px solid #555; border-bottom:1px solid #555; background:#f5f5f5">
    3. Goods Details
  </div>
  <table class="it-tbl">
    <thead>
      <tr>
        <th style="width:10%">HSN Code</th>
        <th>Product Name &amp; Desc.</th>
        <th style="width:10%">Quantity</th>
        <th style="width:12%">Taxable Amt</th>
        <th style="width:15%">Tax Rate (C+S)</th>
      </tr>
    </thead>
    <tbody>
      {% for item in ewb.itemList %}
      <tr>
        <td class="center">{{ item.hsnCode }}</td>
        <td>{{ item.productDesc }}</td>
        <td class="right"><strong>{{ item.quantity }}</strong> {{ item.qtyUnit }}</td>
        <td class="right"><strong>{{ fm(item.taxableAmount) }}</strong></td>
        <td class="center">{{ item.cgstRate|default(0) }}+{{ item.sgstRate|default(0) }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <table style="margin-top:4px; border:1px solid #ccc">
    <tr>
      <td style="width:28%"><span class="lbl">Tot. Taxable Amt :</span> <strong>{{ fm(ewb.totalValue) }}</strong></td>
      <td style="width:16%"><span class="lbl">Other Amt :</span></td>
      <td style="width:28%" class="right"><span class="lbl">Total Inv Amt :</span> <strong>{{ fm(ewb.totInvValue) }}</strong></td>
    </tr>
    <tr>
      <td><span class="lbl">CGST Amt :</span> <strong>{{ fm(ewb.cgstValue) }}</strong></td>
      <td><span class="lbl">SGST Amt :</span> <strong>{{ fm(ewb.sgstValue) }}</strong></td>
      <td></td>
    </tr>
  </table>

  <div style="font-weight:bold; padding:3px 6px; margin:6px 0 4px;
              border-top:1px solid #555; border-bottom:1px solid #555; background:#f5f5f5">
    4. Transportation Details
  </div>
  <table>
    <tr>
      <td style="width:25%"><span class="lbl">Transporter ID :</span></td>
      <td style="width:25%"><span class="lbl">Doc No. :</span></td>
      <td style="width:25%"><span class="lbl">Name :</span></td>
      <td style="width:25%"><span class="lbl">Date :</span></td>
    </tr>
  </table>

  <div style="font-weight:bold; padding:3px 6px; margin:6px 0 4px;
              border-top:1px solid #555; border-bottom:1px solid #555; background:#f5f5f5">
    5. Vehicle Details
  </div>
  <table>
    <tr>
      <td style="width:20%"><span class="lbl">Vehicle No. :</span>
        <strong>{{ vehicle_no | upper }}</strong></td>
      <td style="width:30%"><span class="lbl">From :</span>
        <strong>{{ (ewb.fromPlace or "") | upper }}</strong></td>
      <td style="width:50%"><span class="lbl">CEWB No. :</span></td>
    </tr>
  </table>

</div>
{% endif %}
